<?php
namespace App\Http\Controllers;
use App\Models\House; use Illuminate\Http\Request; use Symfony\Component\HttpFoundation\StreamedResponse;
class DownloadController extends Controller { public function csv(Request $r):StreamedResponse{$q=House::with(['region','structure','floor','wall','roof','sanitation','utility'])->where('is_public',true)->whereIn('status',['verified','published']);foreach(['year'=>'survey_year','region_id'=>'region_id'] as $in=>$col){if($r->filled($in))$q->where($col,$r->integer($in));}return response()->streamDownload(function()use($q){$o=fopen('php://output','w');fputcsv($o,['house_code','wilayah','luas_m2','tahun','sloof','kolom','balok','lantai','dinding','atap','jamban','air_minum','penerangan']);foreach($q->cursor() as $h){$label=fn($id)=>$id??'';fputcsv($o,[$h->house_code,$h->region?->name,$h->area_m2,$h->survey_year,$h->structure?->sloof_condition_id,$h->structure?->column_condition_id,$h->structure?->beam_condition_id,$h->floor?->condition_id,$h->wall?->condition_id,$h->roof?->condition_id,$h->sanitation?->toilet_available?'ADA':'TIDAK PUNYA',$h->sanitation?->water_source_id,$h->utility?->lighting_source_id]);}fclose($o);},'rtlh-cirebon.csv',['Content-Type'=>'text/csv; charset=UTF-8']);} }
